    #[test]
    fn debug_name_and_scope_metadata_is_referentially_closed() {
        let mut func = make_valid_function();
        func.blocks[0].params.push((ValueId::new(0), Ty::I32));
        func.value_names = Some(vec![(ValueId::new(0), "input".to_string())]);
        func.scopes = Some(vec![
            trust_ir::ScopeData {
                parent: None,
                span: None,
            },
            trust_ir::ScopeData {
                parent: Some(0),
                span: None,
            },
        ]);
        func.blocks[0].body[0].scope = Some(1);
        assert!(
            validate_function(&func).is_empty(),
            "well-formed v32/v33 debug metadata must validate"
        );

        let mut duplicate_name = func.clone();
        duplicate_name
            .value_names
            .as_mut()
            .unwrap()
            .push((ValueId::new(0), "alias".to_string()));
        assert!(validate_function(&duplicate_name).iter().any(|error| {
            matches!(
                error,
                ValidationError::InvalidValueName {
                    function: 0,
                    value: 0,
                    ..
                }
            )
        }));

        let mut dangling_name = func.clone();
        dangling_name.value_names = Some(vec![(ValueId::new(99), "ghost".to_string())]);
        assert!(validate_function(&dangling_name).iter().any(|error| {
            matches!(
                error,
                ValidationError::InvalidValueName {
                    function: 0,
                    value: 99,
                    ..
                }
            )
        }));

        let mut malformed_tree = func.clone();
        malformed_tree.scopes.as_mut().unwrap()[1].parent = Some(1);
        assert!(validate_function(&malformed_tree).iter().any(|error| {
            matches!(
                error,
                ValidationError::InvalidScopeTree {
                    function: 0,
                    scope: 1,
                    ..
                }
            )
        }));

        let mut dangling_scope = func;
        dangling_scope.blocks[0].body[0].scope = Some(2);
        assert!(validate_function(&dangling_scope).iter().any(|error| {
            matches!(
                error,
                ValidationError::InvalidInstructionScope {
                    function: 0,
                    block: 0,
                    instruction: 0,
                    scope: 2,
                    scope_count: 2,
                }
            )
        }));
    }

