        let mut module = Module::new("declarations");
        module.add_func_type(FuncTy {
            params: vec![Ty::Ptr],
            returns: vec![Ty::U64],
            is_vararg: false,
        });
        module.add_function(func);
        // ABI pinning: the bodyless external declaration is an FFI boundary,
