    #[test]
    fn ssa_duplicate_value_def() {
        let mut func = Function::new(FuncId::new(0), "dup_def", FuncTyId::new(0), BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        // Define %0 twice via two instruction results
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(1),
            })
            .with_result(ValueId::new(0)),
        );
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I32,
                value: Constant::Int(2),
            })
            .with_result(ValueId::new(0)), // duplicate!
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors
                .iter()
                .any(|e| matches!(e, ValidationError::DuplicateValueDef { value: 0, .. })),
            "expected duplicate value def error, got: {:?}",
            errors
        );
    }

