    #[test]
    fn invalid_cast_variants() {
        // Test that invalid cast combinations produce errors
        let cast_tests: Vec<(CastOp, Ty, Ty)> = vec![
            (CastOp::Trunc, Ty::F64, Ty::I32),   // float src for int-only trunc
            (CastOp::ZExt, Ty::F32, Ty::I64),    // float src for int-only zext
            (CastOp::FPTrunc, Ty::I64, Ty::F32), // int src for float-only fptrunc
            (CastOp::FPToUI, Ty::I32, Ty::I64),  // int src, needs float
            (CastOp::UIToFP, Ty::F64, Ty::F32),  // float src, needs int
            (CastOp::PtrToInt, Ty::I64, Ty::I32), // int src, needs ptr
            (CastOp::IntToPtr, Ty::Ptr, Ty::Ptr), // ptr src, needs int
            (CastOp::Bitcast, Ty::I32, Ty::I64), // different bit widths
            (
                CastOp::ZExt,
                Ty::Vector(Box::new(Ty::Bool), 4),
                Ty::Vector(Box::new(Ty::I32), 4),
            ), // vector resize casts remain fail-closed
        ];

        for (op, src, dst) in cast_tests {
            let mut func = Function::new(
                FuncId::new(0),
                "cast_test",
                FuncTyId::new(0),
                BlockId::new(0),
            );
            let mut block = Block::new(BlockId::new(0));
            block.params.push((ValueId::new(0), src.clone()));
            block.body.push(
                InstrNode::new(Inst::Cast {
                    op,
                    src_ty: src.clone(),
                    dst_ty: dst.clone(),
                    operand: ValueId::new(0),
                })
                .with_result(ValueId::new(1)),
            );
            block
                .body
                .push(InstrNode::new(Inst::Return { values: vec![] }));
            func.blocks.push(block);

            let errors = validate_function(&func);
            assert!(
                errors
                    .iter()
                    .any(|e| matches!(e, ValidationError::CastIncompatible { .. })),
                "expected cast error for {op} {} -> {}, got: {:?}",
                src,
                dst,
                errors
            );
        }
    }

    #[test]
    fn module_validation_accepts_transmute_with_layout_evidence() {
        let mut module = Module::new("layout_casts");
        // Entry block takes the struct as a parameter, so the signature must
        // declare it too (audit #6 EntryParamsMismatch).
        module.add_func_type(FuncTy {
            params: vec![Ty::Struct(StructId::new(0))],
            returns: vec![],
            is_vararg: false,
        });
        let sid = StructId::new(0);
        module.add_struct(StructDef {
            id: sid,
            name: "Pair".into(),
            fields: vec![
                FieldDef {
                    name: "a".into(),
                    ty: Ty::U64,
                    offset: Some(0),
                },
                FieldDef {
                    name: "b".into(),
                    ty: Ty::U64,
                    offset: Some(8),
                },
            ],
            size: Some(16),
            align: Some(8),

            repr: Default::default(),
        });
        let u64_id = module.add_type(Ty::U64);

        let mut func = Function::new(FuncId::new(0), "tx", FuncTyId::new(0), BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), Ty::Struct(sid)));
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::Transmute,
                src_ty: Ty::Struct(sid),
                dst_ty: Ty::Array(u64_id, 2),
                operand: ValueId::new(0),
            })
            .with_result(ValueId::new(1)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        assert!(
            validate_function(&func)
                .iter()
                .any(|e| matches!(e, ValidationError::CastIncompatible { .. }))
        );

        module.add_function(func);
        let errors = validate_module(&module);
        assert!(
            errors.is_empty(),
            "module layout evidence should validate: {errors:?}"
        );
    }

