    #[test]
    fn const_validation_rejects_out_of_range_integer_constants() {
        let mut module = Module::new("const_int_ranges");
        module.globals.push(trust_ir::Global {
            name: "NEG_U8".to_string(),
            ty: Ty::U8,
            mutable: false,
            initializer: Some(Constant::Int(-1)),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        module.globals.push(trust_ir::Global {
            name: "WIDE_I8".to_string(),
            ty: Ty::I8,
            mutable: false,
            initializer: Some(Constant::Int(128)),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        module.globals.push(trust_ir::Global {
            name: "LANES".to_string(),
            ty: Ty::Vector(Box::new(Ty::U8), 2),
            mutable: false,
            initializer: Some(Constant::Vector(vec![Constant::Int(0), Constant::Int(256)])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });

        let errors = validate_module(&module);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'NEG_U8'" && expected == "u8" && actual == "int"
            )),
            "expected unsigned negative integer rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'WIDE_I8'" && expected == "i8" && actual == "int"
            )),
            "expected signed-width integer rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'LANES'" && expected == "<2 x u8>" && actual == "vector[2]"
            )),
            "expected vector lane integer rejection, got {errors:?}"
        );
    }

