    #[test]
    fn tuple_struct_and_record_constants_are_recursively_checked() {
        let mut module = Module::new("aggregate_consts");
        let struct_id = module.add_struct(StructDef {
            id: StructId::new(0),
            name: "Pair".to_string(),
            fields: vec![
                FieldDef {
                    name: "byte".to_string(),
                    ty: Ty::U8,
                    offset: Some(0),
                },
                FieldDef {
                    name: "enabled".to_string(),
                    ty: Ty::Bool,
                    offset: Some(1),
                },
            ],
            size: Some(2),
            align: Some(1),

            repr: Default::default(),
        });
        let record_id = module.add_record(RecordDef {
            id: RecordId::new(0),
            name: "LogicalPair".to_string(),
            fields: vec![
                FieldDef {
                    name: "byte".to_string(),
                    ty: Ty::U8,
                    offset: None,
                },
                FieldDef {
                    name: "enabled".to_string(),
                    ty: Ty::Bool,
                    offset: None,
                },
            ],
        });
        module.globals.push(trust_ir::Global {
            name: "GOOD_TUPLE".to_string(),
            ty: Ty::Tuple(vec![Ty::U8, Ty::Bool]),
            mutable: false,
            initializer: Some(Constant::Aggregate(vec![
                Constant::Int(42),
                Constant::Bool(true),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        module.globals.push(trust_ir::Global {
            name: "BAD_STRUCT".to_string(),
            ty: Ty::Struct(struct_id),
            mutable: false,
            initializer: Some(Constant::Aggregate(vec![
                Constant::Int(300),
                Constant::Bool(true),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        module.globals.push(trust_ir::Global {
            name: "BAD_RECORD".to_string(),
            ty: Ty::Record(record_id),
            mutable: false,
            initializer: Some(Constant::Record(vec![
                ("byte".to_string(), Constant::Int(7)),
                ("enabled".to_string(), Constant::Int(1)),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });

        let errors = validate_module(&module);
        assert!(
            !errors.iter().any(|e| {
                matches!(
                    e,
                    ValidationError::ConstTypeMismatch { location, .. }
                        if location.starts_with("global 'GOOD_TUPLE'")
                )
            }),
            "valid tuple aggregate should not be rejected, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'BAD_STRUCT'[0]"
                        && expected == "u8"
                        && actual == "int"
            )),
            "expected struct field range rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'BAD_RECORD'.enabled"
                        && expected == "bool"
                        && actual == "int"
            )),
            "expected record field type rejection, got {errors:?}"
        );
    }

    #[test]
    fn vector_function_signature_global_and_struct_types_are_validated() {
        let mut module = Module::new("vector_decls");
        module.add_func_type(FuncTy {
            params: vec![Ty::Vector(Box::new(Ty::Ptr), 4)],
            returns: vec![Ty::Vector(Box::new(Ty::I32), 0)],
            is_vararg: false,
        });
        module.globals.push(trust_ir::Global {
            name: "bad_global".to_string(),
            ty: Ty::Vector(Box::new(Ty::Ptr), 4),
            mutable: false,
            initializer: None,
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        module.add_struct(StructDef {
            id: StructId::new(0),
            name: "BadVecField".to_string(),
            fields: vec![FieldDef {
                name: "lanes".to_string(),
                ty: Ty::Vector(Box::new(Ty::Vector(Box::new(Ty::I32), 4)), 2),
                offset: None,
            }],
            size: None,
            align: None,

            repr: Default::default(),
        });

        let errors = validate_module(&module);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidModuleVectorType { location, reason, .. }
                    if location == "functy.0 param 0"
                        && reason == "lane type must be bool, integer, or float"
            )),
            "expected invalid vector function param, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidModuleVectorType { location, reason, .. }
                    if location == "functy.0 return 0"
                        && reason == "lane count must be nonzero"
            )),
            "expected invalid vector function return, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidModuleVectorType { location, .. }
                    if location == "global 'bad_global'"
            )),
            "expected invalid vector global type, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidModuleVectorType { location, reason, .. }
                    if location == "struct @BadVecField field 'lanes'"
                        && reason == "nested vector lanes are not supported"
            )),
            "expected invalid vector struct field, got {errors:?}"
        );
    }

