    #[test]
    fn vector_select_requires_lane_mask_and_rejects_mismatches() {
        let v4i32 = Ty::v4_i32();
        let v4bool = Ty::v4_bool();
        let v2bool = Ty::Vector(Box::new(Ty::Bool), 2);
        let mut func = Function::new(
            FuncId::new(0),
            "vector_select_masks",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), v4bool));
        block.params.push((ValueId::new(1), v2bool));
        block.params.push((ValueId::new(2), Ty::Bool));
        block.params.push((ValueId::new(3), v4i32.clone()));
        block.params.push((ValueId::new(4), v4i32.clone()));
        block.params.push((ValueId::new(5), Ty::I32));

        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(0),
                then_val: ValueId::new(3),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(6)),
        );
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(2),
                then_val: ValueId::new(3),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(7)),
        );
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(1),
                then_val: ValueId::new(3),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(8)),
        );
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: v4i32.clone(),
                cond: ValueId::new(0),
                then_val: ValueId::new(5),
                else_val: ValueId::new(4),
            })
            .with_result(ValueId::new(9)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::SelectConditionTypeMismatch {
                    expected,
                    actual,
                    ..
                } if expected == "<4 x bool>" && actual == "bool"
            )),
            "expected scalar bool select condition rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::SelectConditionTypeMismatch {
                    expected,
                    actual,
                    ..
                } if expected == "<4 x bool>" && actual == "<2 x bool>"
            )),
            "expected lane-mask select condition rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::OperandTypeMismatch { op, expected, actual, .. }
                    if op == "select" && actual == "i32" && expected == "<4 x i32>"
            )),
            "expected select payload type rejection, got {errors:?}"
        );
        assert_eq!(
            errors
                .iter()
                .filter(|e| matches!(e, ValidationError::SelectConditionTypeMismatch { .. }))
                .count(),
            2,
            "only the scalar bool and wrong-lane mask should fail condition validation: {errors:?}"
        );
    }

