    #[test]
    fn vector_extract_insert_element_rejects_malformed_operands() {
        let v4i32 = Ty::v4_i32();
        let mut func = Function::new(
            FuncId::new(0),
            "bad_vector_elements",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let mut block = Block::new(BlockId::new(0));
        block.params.push((ValueId::new(0), Ty::I32));
        block.params.push((ValueId::new(1), v4i32.clone()));
        block.params.push((ValueId::new(2), Ty::F32));
        block.params.push((ValueId::new(3), Ty::F32));
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I64,
                value: Constant::Int(4),
            })
            .with_result(ValueId::new(4)),
        );
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I64,
                value: Constant::Int(-1),
            })
            .with_result(ValueId::new(5)),
        );
        block.body.push(
            InstrNode::new(Inst::ExtractElement {
                ty: Ty::I32,
                array: ValueId::new(0),
                index: ValueId::new(2),
            })
            .with_result(ValueId::new(6)),
        );
        block.body.push(
            InstrNode::new(Inst::ExtractElement {
                ty: Ty::I64,
                array: ValueId::new(1),
                index: ValueId::new(4),
            })
            .with_result(ValueId::new(7)),
        );
        block.body.push(
            InstrNode::new(Inst::InsertElement {
                ty: Ty::I32,
                array: ValueId::new(1),
                index: ValueId::new(5),
                value: ValueId::new(3),
            })
            .with_result(ValueId::new(8)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "extract_element"
                        && reason == "operand must be vector or array, got i32"
            )),
            "expected non-vector extract rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "extract_element" && reason == "index must be integer, got f32"
            )),
            "expected non-integer index rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "extract_element"
                        && reason == "result type must match vector lane type i32, got i64"
            )),
            "expected extract result/lane mismatch, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "extract_element"
                        && reason == "constant lane index 4 is out of range for 4 lanes"
            )),
            "expected extract constant lane bounds rejection, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "insert_element"
                        && reason == "result type must match operand type <4 x i32>, got i32"
            )),
            "expected insert result/vector mismatch, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "insert_element"
                        && reason == "inserted value must match vector lane type i32, got f32"
            )),
            "expected insert lane value mismatch, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::InvalidVectorElementOp { op, reason, .. }
                    if op == "insert_element"
                        && reason == "constant lane index -1 is out of range for 4 lanes"
            )),
            "expected insert constant lane bounds rejection, got {errors:?}"
        );
    }

