    #[test]
    fn vector_constant_kind_lane_count_and_element_shapes_must_match() {
        let mut valid = Module::new("good_vector_consts");
        let valid_func_ty = valid.add_func_type(FuncTy {
            params: vec![],
            returns: vec![],
            is_vararg: false,
        });
        valid.globals.push(trust_ir::Global {
            name: "ZEROS".to_string(),
            ty: Ty::Vector(Box::new(Ty::I32), 4),
            mutable: false,
            initializer: Some(Constant::zero_i32_vector(4)),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        let mut valid_func = Function::new(FuncId::new(0), "f", valid_func_ty, BlockId::new(0));
        let mut valid_block = Block::new(BlockId::new(0));
        valid_block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::Vector(Box::new(Ty::Bool), 4),
                value: Constant::vector_bool([true, false, true, false]),
            })
            .with_result(ValueId::new(0)),
        );
        valid_block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        valid_func.blocks.push(valid_block);
        valid.add_function(valid_func);
        assert!(
            validate_module(&valid).is_empty(),
            "canonical vector constants should validate"
        );

        let mut module = Module::new("bad_vector_consts");
        let func_ty = module.add_func_type(FuncTy {
            params: vec![],
            returns: vec![],
            is_vararg: false,
        });
        module.globals.push(trust_ir::Global {
            name: "MASK".to_string(),
            ty: Ty::Vector(Box::new(Ty::Bool), 2),
            mutable: false,
            initializer: Some(Constant::Vector(vec![
                Constant::Bool(true),
                Constant::Int(1),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });
        module.globals.push(trust_ir::Global {
            name: "OLD_ARRAY".to_string(),
            ty: Ty::Vector(Box::new(Ty::I32), 4),
            mutable: false,
            initializer: Some(Constant::Array(vec![
                Constant::Int(1),
                Constant::Int(2),
                Constant::Int(3),
                Constant::Int(4),
            ])),
            linkage: trust_ir::Linkage::Internal,
            tls: None,
            align: None,
        });

        let mut func = Function::new(FuncId::new(0), "f", func_ty, BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::Vector(Box::new(Ty::I32), 4),
                value: Constant::Vector(vec![Constant::Int(1), Constant::Int(2)]),
            })
            .with_result(ValueId::new(0)),
        );
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);
        module.add_function(func);

        let errors = validate_module(&module);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'MASK'"
                        && expected == "<2 x bool>"
                        && actual == "vector[2]"
            )),
            "expected vector element-shape mismatch, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "global 'OLD_ARRAY'"
                        && expected == "<4 x i32>"
                        && actual == "array[4]"
            )),
            "expected array constants to be rejected for vector declarations, got {errors:?}"
        );
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::ConstTypeMismatch { location, expected, actual }
                    if location == "function 'f' bb0"
                        && expected == "<4 x i32>"
                        && actual == "vector[2]"
            )),
            "expected vector lane-count mismatch, got {errors:?}"
        );
    }

    // --- Module-Level Duplicate Tests ---

    #[test]
    fn duplicate_struct_id_error() {
        let mut module = Module::new("dup_struct");
        let func_ty = module.add_func_type(FuncTy {
            params: vec![],
            returns: vec![],
            is_vararg: false,
        });

        let mut func = Function::new(FuncId::new(0), "main", func_ty, BlockId::new(0));
        let mut block = Block::new(BlockId::new(0));
        block
            .body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(block);
        module.add_function(func);

        module.add_struct(StructDef {
            id: StructId::new(0),
            name: "Foo".to_string(),
            fields: vec![FieldDef {
                name: "x".to_string(),
                ty: Ty::I32,
                offset: None,
            }],
            size: None,
            align: None,

            repr: Default::default(),
        });
        module.add_struct(StructDef {
            id: StructId::new(0), // duplicate!
            name: "Bar".to_string(),
            fields: vec![],
            size: None,
            align: None,

            repr: Default::default(),
        });

        let errors = validate_module(&module);
        assert!(errors.contains(&ValidationError::DuplicateStructId(0)));
    }

    // ============================================================
    // Binding frame validation tests (item 4 of TrustIr#30)
    // ============================================================
    //
    // These tests cover the discipline laid out in
    // `designs/2026-04-18-ty-supremacy-trust-ir-scope.md` §R4:
    // unique frame ids, well-scoped frame-handle use, typed slot access,
    // LIFO open/close, and rejection of common malformed shapes.

    use trust_ir::inst::{BindingFrameDef, BindingSlot};
    use trust_ir::value::BindingFrameId;

    /// Construct a simulated `\E i \in [0..N] : P(i)` lowering and validate
    /// that it passes all checks. This is the positive-path canary for the
    /// quantifier-lowering scenario that originally motivated binding
    /// frames (the Cranelift JIT ceiling).
    ///
    /// Function layout:
    ///   bb0 (entry):
    ///     %n = const I64 4         ; upper bound (N=4)
    ///     %i0 = const I64 0        ; induction start
    ///     %f0 = open_frame #0 {i: I64}
    ///     br bb1(%i0, %f0)
    ///   bb1(%i: I64, %f_in: Ptr):
    ///     %cont = icmp slt %i, %n
    ///     cond_br %cont, bb2(%i, %f_in), bb3(%f_in)
    ///   bb2(%i_cur: I64, %f_in2: Ptr):
    ///     %f_bound = bind_slot %f_in2, 0, %i_cur
    ///     %i_loaded = load_slot I64 %f_bound, 0   ; models "use of binding"
    ///     ... (skip actual P(i) call for simplicity; just re-branch)
    ///     %i_next = binop add I64 %i_cur, 1      ; increment
    ///     br bb1(%i_next, %f_bound)
    ///   bb3(%f_exit: Ptr):
    ///     close_frame %f_exit
    ///     return
    fn build_exists_lowering() -> Function {
        let mut func = Function::new(
            FuncId::new(0),
            "exists_i_in_N",
            FuncTyId::new(0),
            BlockId::new(0),
        );

        // Reusable ids
        let v = ValueId::new;
        let bb = BlockId::new;

        // bb0: entry
        let mut b0 = Block::new(bb(0));
        b0.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I64,
                value: Constant::Int(4),
            })
            .with_result(v(100)), // %n
        );
        b0.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I64,
                value: Constant::Int(0),
            })
            .with_result(v(101)), // %i0
        );
        b0.body.push(
            InstrNode::new(Inst::OpenFrame {
                def: BindingFrameDef::new(
                    BindingFrameId::new(0),
                    "exists_i",
                    vec![BindingSlot::new("i", Ty::I64)],
                ),
            })
            .with_result(v(102)), // %f0
        );
        b0.body.push(InstrNode::new(Inst::Br {
            target: bb(1),
            args: vec![v(101), v(102)],
        }));
        func.blocks.push(b0);

        // bb1: loop header  (%i: I64, %f_in: Ptr)
        let mut b1 = Block::new(bb(1));
        b1.params.push((v(110), Ty::I64));
        b1.params.push((v(111), Ty::Ptr));
        b1.body.push(
            InstrNode::new(Inst::ICmp {
                op: ICmpOp::Slt,
                ty: Ty::I64,
                lhs: v(110),
                rhs: v(100),
            })
            .with_result(v(112)),
        );
        b1.body.push(InstrNode::new(Inst::CondBr {
            cond: v(112),
            then_target: bb(2),
            then_args: vec![v(110), v(111)],
            else_target: bb(3),
            else_args: vec![v(111)],
        }));
        func.blocks.push(b1);

        // bb2: loop body  (%i_cur: I64, %f_in2: Ptr)
        let mut b2 = Block::new(bb(2));
        b2.params.push((v(120), Ty::I64));
        b2.params.push((v(121), Ty::Ptr));
        b2.body.push(
            InstrNode::new(Inst::BindSlot {
                frame: v(121),
                slot: 0,
                value: v(120),
            })
            .with_result(v(122)), // %f_bound
        );
        b2.body.push(
            InstrNode::new(Inst::LoadSlot {
                frame: v(122),
                slot: 0,
                ty: Ty::I64,
            })
            .with_result(v(123)), // %i_loaded
        );
        // Increment: %i_next = %i_cur + 1
        b2.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I64,
                value: Constant::Int(1),
            })
            .with_result(v(124)),
        );
        b2.body.push(
            InstrNode::new(Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I64,
                lhs: v(120),
                rhs: v(124),
            })
            .with_result(v(125)),
        );
        // Loop back: note we pass the *new* frame handle to respect SSA
        b2.body.push(InstrNode::new(Inst::Br {
            target: bb(1),
            args: vec![v(125), v(122)],
        }));
        func.blocks.push(b2);

        // bb3: exit (%f_exit: Ptr) — close and return
        let mut b3 = Block::new(bb(3));
        b3.params.push((v(130), Ty::Ptr));
        b3.body
            .push(InstrNode::new(Inst::CloseFrame { frame: v(130) }));
        b3.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b3);

        func
    }

    #[test]
    fn exists_lowering_validates_clean() {
        let func = build_exists_lowering();
        let errors = validate_function(&func);
        assert!(
            errors.is_empty(),
            "expected clean lowering, got errors: {:?}",
            errors
        );
    }

    #[test]
    fn binding_slot_out_of_range_is_rejected() {
        let mut func = Function::new(
            FuncId::new(0),
            "bad_slot",
            FuncTyId::new(0),
            BlockId::new(0),
        );
        let v = ValueId::new;
        let bb = BlockId::new;
        let mut b0 = Block::new(bb(0));
        b0.body.push(
            InstrNode::new(Inst::OpenFrame {
                def: BindingFrameDef::new(
                    BindingFrameId::new(0),
                    "f",
                    vec![BindingSlot::new("i", Ty::I64)],
                ),
            })
            .with_result(v(10)),
        );
        b0.body.push(
            InstrNode::new(Inst::Const {
                ty: Ty::I64,
                value: Constant::Int(0),
            })
            .with_result(v(11)),
        );
        // slot 5 is out of range for arity 1
        b0.body.push(
            InstrNode::new(Inst::BindSlot {
                frame: v(10),
                slot: 5,
                value: v(11),
            })
            .with_result(v(12)),
        );
        b0.body
            .push(InstrNode::new(Inst::CloseFrame { frame: v(12) }));
        b0.body
            .push(InstrNode::new(Inst::Return { values: vec![] }));
        func.blocks.push(b0);

        let errors = validate_function(&func);
        assert!(
            errors.iter().any(|e| matches!(
                e,
                ValidationError::BindingSlotOutOfRange {
                    frame_id: 0,
                    slot: 5,
                    arity: 1,
                    ..
                }
            )),
            "expected BindingSlotOutOfRange, got {:?}",
            errors
        );
    }

